// @name Word guess
// @background #f3f0e8
// @refresh 3600
// Guess the five-letter word in six tries. Each guess marks its letters: in
// the right spot, in the word but elsewhere, or not in it, and the keyboard
// keeps the score. A daily word (the same for everyone that day) or endless
// words, with stats kept on the frame. Type on the keys on the screen, or on
// a keyboard on a Pi.
import { ANSWERS, MORE_WORDS } from './words'
import { score, letterStates, dayNumber, dailyIndex } from './logic'
import { highContrast, canvasOf, Button, OptionsPage } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f3f0e8] text-[#1f2a30]',
    muted: 'text-[#5f6a70]',
    button: 'bg-[#e1dccf] text-[#1f2a30] active:bg-[#d2cbba]',
    primary: 'bg-[#3e6b4f] text-white active:bg-[#4d8262]',
    on: 'bg-[#3e6b4f] text-white',
    off: 'bg-[#e1dccf] text-[#1f2a30]',
    empty: 'border-2 border-[#d4cdbd]',
    typing: 'border-2 border-[#6b7378]',
    c: 'bg-[#3e6b4f] text-white',
    p: 'bg-[#c99a2e] text-white',
    a: 'bg-[#7d858a] text-white',
    key: 'bg-[#e1dccf] text-[#1f2a30] active:bg-[#d2cbba]',
    bar: 'bg-[#7d858a] text-white',
    barNow: 'bg-[#3e6b4f] text-white',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    empty: 'border border-black',
    typing: 'border-2 border-black',
    // Never by color alone: filled is the right spot, a double frame is in
    // the word elsewhere, a bare letter is not in it.
    c: 'bg-black text-white',
    p: 'double',
    a: 'bg-white text-black',
    key: 'bg-white text-black border-2 border-black',
    bar: 'bg-white text-black border-2 border-black',
    barNow: 'bg-black text-white',
  },
}

const ROWS = ['qwertyuiop', 'asdfghjkl', 'zxcvbnm']
const PRAISE = ['Genius!', 'Magnificent!', 'Impressive!', 'Splendid!', 'Great!', 'Phew!']

const answerList = () => ANSWERS.split(' ')
const isWord = (word: string) => (' ' + ANSWERS + ' ').indexOf(` ${word} `) >= 0 || MORE_WORDS.indexOf(` ${word} `) >= 0
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1'
const settingsOf = (app) => ({
  daily: app.state.mode !== 'endless',
  anyWord: app.state.acceptAnyWord === undefined || app.state.acceptAnyWord === null || app.state.acceptAnyWord === '' ? true : truthy(app.state.acceptAnyWord),
})

// The game in progress, kept in the scene's private `game` field: the mode,
// the day (daily) or a counter (endless), which answer, the guesses.
type Game = { mode: string; day: number; round: number; answer: number; guesses: string[]; done: boolean; won: boolean }
const loadGame = (app): Game | null => {
  const g = app.state.game
  return g && Array.isArray(g.guesses) && typeof g.answer === 'number' ? g : null
}
const save = (game: Game) => frameos.setState('game', game)

type ModeStats = { played: number; wins: number; streak: number; best: number; dist: number[]; lastDay: number }
const emptyStats = (): ModeStats => ({ played: 0, wins: 0, streak: 0, best: 0, dist: [0, 0, 0, 0, 0, 0], lastDay: -1 })
const loadStats = (app, mode: string): ModeStats => {
  const all = app.state.stats && typeof app.state.stats === 'object' ? app.state.stats : {}
  const s = all[mode]
  return s && Array.isArray(s.dist) ? s : emptyStats()
}
const saveStats = (app, mode: string, stats: ModeStats) => {
  const all = app.state.stats && typeof app.state.stats === 'object' ? { ...app.state.stats } : {}
  all[mode] = stats
  frameos.setState('stats', all)
}

const newGame = (app, daily: boolean, previous: Game | null): Game => {
  const count = answerList().length
  const today = dayNumber(new Date())
  frameos.remember('draft', '')
  frameos.remember('message', '')
  if (daily) return { mode: 'daily', day: today, round: 0, answer: dailyIndex(today, count), guesses: [], done: false, won: false }
  // An endless word: random, but never the one just played.
  let answer = Math.floor(Math.random() * count)
  if (previous && previous.answer === answer) answer = (answer + 1) % count
  return { mode: 'endless', day: today, round: (previous?.round || 0) + 1, answer, guesses: [], done: false, won: false }
}

const draftOf = () => String(frameos.recall('draft') || '')
const say = (message: string) => frameos.remember('message', message)

// A letter, a backspace or Enter, from the keys on the screen or a keyboard.
const press = (app, key: string) => {
  const game = loadGame(app)
  if (!game || game.done) return
  let draft = draftOf()
  say('')
  if (key === 'enter') {
    submit(app, game, draft)
    return
  }
  if (key === 'back') draft = draft.slice(0, -1)
  else if (/^[a-z]$/.test(key) && draft.length < 5) draft += key
  frameos.remember('draft', draft)
}

const submit = (app, game: Game, guess: string) => {
  if (guess.length < 5) {
    say('Five letters, please')
    return
  }
  const answer = answerList()[game.answer]
  if (!settingsOf(app).anyWord && guess !== answer && !isWord(guess)) {
    say(`"${guess.toUpperCase()}" is not in the word list`)
    return
  }
  const guesses = [...game.guesses, guess]
  const won = guess === answer
  const done = won || guesses.length === 6
  save({ ...game, guesses, done, won })
  frameos.remember('draft', '')
  if (!done) return
  // The stats for this mode. A daily streak needs yesterday's word solved.
  const stats = loadStats(app, game.mode)
  stats.played++
  if (won) {
    stats.wins++
    stats.dist[guesses.length - 1]++
    stats.streak = game.mode === 'daily' && stats.lastDay !== game.day - 1 ? 1 : stats.streak + 1
    stats.best = Math.max(stats.best, stats.streak)
  } else stats.streak = 0
  stats.lastDay = game.day
  saveStats(app, game.mode, stats)
}

// A real keyboard on a Pi: letters, Backspace and Enter. Forward is the next
// endless word once one is done, on frames with buttons.
export function onEvent(app, context) {
  if (context.event === 'forward') {
    const game = loadGame(app)
    if (!game || !game.done || game.mode !== 'endless') return false
    save(newGame(app, false, game))
    return true
  }
  if (context.event !== 'keyDown') return false
  const p = context.payload || {}
  if (p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '')
  if (key === 'Enter') press(app, 'enter')
  else if (key === 'Backspace') press(app, 'back')
  else if (/^[a-zA-Z]$/.test(key)) press(app, key.toLowerCase())
  else return false
  return true
}

// One square of the grid, or one key: `mark` is "c", "p", "a", or the look of
// an empty or typed square.
const Square = ({ t, mark, className, children, onClick }: any) => {
  const look = mark === 'c' || mark === 'p' || mark === 'a' ? t[mark] : mark === 'typing' ? t.typing : mark === 'key' ? t.key : t.empty
  if (look === 'double') {
    // High contrast's "elsewhere": a frame inside a frame.
    return (
      <div className={`${className} bg-white text-black border-[3px] border-black p-[3px]`} onClick={onClick}>
        <div className="w-full h-full border-2 border-black rounded-[3px] flex items-center justify-center">{children}</div>
      </div>
    )
  }
  return (
    <div className={`${className} flex items-center justify-center ${look}`} onClick={onClick}>
      {children}
    </div>
  )
}

const Grid = ({ t, game, draft, tile, gap }) => {
  const answer = answerList()[game.answer]
  const rows = []
  for (let r = 0; r < 6; r++) {
    const guess = game.guesses[r]
    const marks = guess ? score(guess, answer) : ''
    const typing = !guess && r === game.guesses.length && !game.done
    const cells = []
    for (let i = 0; i < 5; i++) {
      const letter = guess ? guess[i] : typing ? draft[i] || '' : ''
      const mark = guess ? marks[i] : typing && letter ? 'typing' : 'empty'
      cells.push(
        <Square t={t} mark={mark} className={`w-[${tile}px] h-[${tile}px] rounded-md text-[${Math.round(tile * 0.55)}px] font-bold uppercase`}>
          {letter}
        </Square>,
      )
    }
    rows.push(<div className={`flex gap-[${gap}px]`}>{cells}</div>)
  }
  return <div className={`flex flex-col gap-[${gap}px]`}>{rows}</div>
}

// The keys, `width` across: ten keys a row, the middle row set in by half a
// key, Enter and Del a key and a half wide.
const Keyboard = ({ app, t, states, width, keyH, text, gap }) => {
  const keyW = Math.floor((width - gap * 9) / 10)
  const wideW = Math.floor(keyW * 1.5 + gap / 2)
  const key = (k: string, label: string, w: number) => (
    <Square t={t} mark={states[k] || 'key'} onClick={() => press(app, k)}
      className={`w-[${w}px] h-[${keyH}px] rounded-lg whitespace-nowrap font-bold ${label.length === 1 ? `uppercase text-[${text}px]` : `text-[${Math.round(text * 0.8)}px]`}`}>
      {label}
    </Square>
  )
  return (
    <div className={`flex flex-col items-center gap-[${gap}px] w-[${width}px]`}>
      <div className={`flex gap-[${gap}px]`}>{ROWS[0].split('').map((k) => key(k, k, keyW))}</div>
      <div className={`flex gap-[${gap}px]`}>{ROWS[1].split('').map((k) => key(k, k, keyW))}</div>
      <div className={`flex gap-[${gap}px]`}>
        {key('enter', 'Enter', wideW)}
        {ROWS[2].split('').map((k) => key(k, k, keyW))}
        {key('back', 'Del', wideW)}
      </div>
    </div>
  )
}

// The end of a game: how it went, the stats for the mode, what next.
const Result = ({ app, ui, t, game, stats, compact }) => {
  const answer = answerList()[game.answer]
  const headline = game.won ? PRAISE[game.guesses.length - 1] : answer.toUpperCase()
  const sub = game.won ? `${game.guesses.length} of 6` : 'was the word'
  const winRate = stats.played ? Math.round((stats.wins * 100) / stats.played) : 0
  const most = Math.max(1, ...stats.dist)
  const number = (value, label) => (
    <div className="flex-1 flex flex-col items-center">
      <span className={`text-[${ui.big}px] font-bold leading-tight`}>{String(value)}</span>
      <span className={`text-[${Math.round(ui.small * 0.85)}px] ${t.muted}`}>{label}</span>
    </div>
  )
  const next = game.mode === 'endless'
    ? <Button ui={ui} grow className={t.primary} onClick={() => save(newGame(app, false, game))}>Next word</Button>
    : <Button ui={ui} grow className={t.button} onClick={() => frameos.setState('mode', 'endless')}>Practice</Button>
  return (
    <div className={`flex flex-col w-full gap-[${ui.gap}px]`}>
      <div className={`flex items-end gap-[${ui.gap}px]`}>
        <span className={`text-[${ui.title}px] font-bold leading-tight`}>{headline}</span>
        <span className={`text-[${ui.text}px] ${t.muted} pb-[4px]`}>{sub}</span>
      </div>
      <div className="flex">
        {number(stats.played, 'played')}
        {number(winRate, 'win %')}
        {number(stats.streak, 'streak')}
        {number(stats.best, 'best streak')}
      </div>
      {compact ? null : (
        <div className="flex flex-col gap-[4px]">
          {stats.dist.map((n, i) => (
            <div className={`flex items-center gap-[8px] text-[${ui.small}px]`}>
              <span className="w-[16px] font-bold">{String(i + 1)}</span>
              <div className="flex-1">
                <div className={`w-[${Math.max(8, Math.round((n * 100) / most))}%] min-w-[30px] h-[${Math.round(ui.small * 1.35)}px] rounded flex items-center justify-end px-[6px] font-bold ${game.won && game.guesses.length === i + 1 ? t.barNow : t.bar}`}>
                  {String(n)}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
      <div className={`flex items-center gap-[${ui.gap}px]`}>
        {game.mode === 'daily' ? <span className={`flex-1 text-[${ui.small}px] ${t.muted}`}>A new word at midnight</span> : null}
        {next}
      </div>
    </div>
  )
}

export function get(app, context) {
  const ui = canvasOf(app, context)
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows = [
      { field: 'mode', label: 'Word', value: settings.daily ? 'daily' : 'endless', options: [['daily', 'Daily'], ['endless', 'Endless']] },
      { field: 'acceptAnyWord', label: 'Guesses', value: settings.anyWord ? 'true' : 'false', options: [['true', 'Any five letters'], ['false', 'Listed words']] },
    ]
    return <OptionsPage ui={ui} t={t} title="Word guess" rows={rows}
      onClose={() => frameos.remember('page', null)}
      onNew={() => {
        save(newGame(app, settingsOf(app).daily, loadGame(app)))
        frameos.remember('page', null)
      }} />
  }

  // Today's word, a new day's, or an endless one when the mode changed.
  const today = dayNumber(new Date())
  let game = loadGame(app)
  if (!game || (settings.daily ? game.mode !== 'daily' || game.day !== today : game.mode !== 'endless')) {
    game = newGame(app, settings.daily, game)
    save(game)
  }
  const draft = draftOf()
  const message = String(frameos.recall('message') || '')
  const states = letterStates(game.guesses, answerList()[game.answer])
  const stats = loadStats(app, game.mode)
  const when = new Date()
  const subtitle = game.mode === 'daily'
    ? `Daily · ${when.getDate()} ${MONTHS[when.getMonth()]}`
    : `Endless · word ${game.round}`

  const side = ui.W >= ui.H * 1.15
  const gap = Math.max(4, Math.round(ui.gap * 0.6))
  const header = (
    <div className={`flex items-center gap-[${ui.gap}px] w-full`}>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${ui.big}px] font-bold leading-tight`}>Word guess</span>
        <span className={`text-[${ui.small}px] ${t.muted} truncate`}>{message || subtitle}</span>
      </div>
      <Button ui={ui} className={t.button} onClick={() => frameos.remember('page', 'options')}>Options</Button>
    </div>
  )

  if (side) {
    // The grid on the left at full height, the keyboard (or the result) on the right.
    const tile = Math.floor(Math.min((ui.H - ui.pad * 2 - gap * 5) / 6, (ui.W * 0.42 - gap * 4) / 5))
    const rightW = ui.W - ui.pad * 3 - tile * 5 - gap * 4
    // Keys as tall as the room allows, but never more than twice as tall as wide.
    const keyW = (rightW - gap * 9) / 10
    const keyH = Math.round(Math.max(44, Math.min(((ui.H - ui.pad * 2 - ui.button - ui.gap * 2 - gap * 2) / 3) * 0.8, keyW * 2)))
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        <Grid t={t} game={game} draft={draft} tile={tile} gap={gap} />
        <div className={`w-[${rightW}px] h-full flex flex-col gap-[${ui.gap}px]`}>
          {header}
          <div className="flex-1 flex items-center">
            {game.done
              ? <Result app={app} ui={ui} t={t} game={game} stats={stats} compact={ui.H < 420} />
              : <Keyboard app={app} t={t} states={states} width={rightW} keyH={keyH} text={Math.round(Math.min(keyH * 0.42, rightW / 18))} gap={gap} />}
          </div>
        </div>
      </div>
    )
  }
  // Stacked: the header, the grid, the keyboard (or the result) below. The
  // grid takes what the rest leaves; the result drops its bars when the grid
  // would get too small.
  const keyH = Math.max(40, Math.round(Math.min(ui.H * 0.085, ui.W / 9)))
  const keysH = keyH * 3 + gap * 2
  const resultH = (full: boolean) =>
    ui.title * 1.25 + ui.big * 1.25 + ui.small * 1.2 + ui.button + ui.gap * 3 + (full ? 6 * (Math.round(ui.small * 1.35) + 4) + ui.gap : 0)
  const tileFor = (below: number) =>
    Math.floor(Math.min((ui.H - ui.pad * 2 - ui.button - below - ui.gap * 3 - gap * 5) / 6, (ui.W - ui.pad * 2 - gap * 4) / 5, ui.W / 7))
  const full = game.done && tileFor(resultH(true)) >= Math.max(36, ui.H * 0.06)
  const tile = tileFor(game.done ? resultH(full) : keysH)
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] items-center ${t.page}`}>
      {header}
      <div className="flex-1 flex items-center justify-center">
        <Grid t={t} game={game} draft={draft} tile={tile} gap={gap} />
      </div>
      {game.done
        ? <Result app={app} ui={ui} t={t} game={game} stats={stats} compact={!full} />
        : <Keyboard app={app} t={t} states={states} width={ui.W - ui.pad * 2} keyH={keyH} text={Math.round(Math.min(keyH * 0.45, ui.W / 20))} gap={gap} />}
    </div>
  )
}

