// Word guess's rules. Pure: no frameos calls, so it can be checked with
// plain node.

// Each letter of a guess against the answer: "c" in the right spot, "p" in
// the word but elsewhere, "a" not in it (or not as many times). Right spots
// are counted first, so a doubled letter is marked only as often as the
// answer has it.
export function score(guess: string, answer: string) {
  const marks = ['a', 'a', 'a', 'a', 'a']
  const left: Record<string, number> = {}
  for (let i = 0; i < 5; i++) {
    if (guess[i] === answer[i]) marks[i] = 'c'
    else left[answer[i]] = (left[answer[i]] || 0) + 1
  }
  for (let i = 0; i < 5; i++) {
    if (marks[i] === 'c') continue
    if (left[guess[i]]) {
      marks[i] = 'p'
      left[guess[i]]--
    }
  }
  return marks.join('')
}

// The best each letter has done so far, for the keyboard: c beats p beats a.
export function letterStates(guesses: string[], answer: string) {
  const states: Record<string, string> = {}
  const rank = { a: 1, p: 2, c: 3 }
  for (const guess of guesses) {
    const marks = score(guess, answer)
    for (let i = 0; i < 5; i++) {
      const letter = guess[i]
      if (!states[letter] || rank[marks[i]] > rank[states[letter]]) states[letter] = marks[i]
    }
  }
  return states
}

// Days since 1 January 1970 in the frame's own time zone, so the daily word
// changes at local midnight.
export function dayNumber(date: Date) {
  return Math.floor(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / 86400000)
}

// The day's word: a fixed walk through the list that visits every word once
// before any comes back (the step and the list's length share no factor).
export function dailyIndex(day: number, count: number) {
  let step = 271
  while (gcd(step, count) !== 1) step++
  return (((day * step + 89) % count) + count) % count
}

function gcd(a: number, b: number): number {
  return b ? gcd(b, a % b) : a
}

